    'web.challenge.f.title.ph': 'قم بتسمية مشروعك',
    'web.challenge.f.url.label': 'رابط المشروع أو فيديو العرض التوضيحي',
    'web.challenge.f.url.ph': 'https:// رابط صالح أو فيديو',
    'web.challenge.faq.a1': 'نعم. يتم إصدار المكافآت إلى حساب Manyfold الخاص بك، لذا يتطلب الانضمام وجود حساب مسجل الدخول، ولا حاجة لنسخ معرف المستخدم. هل أنت جديد في Manyfold؟ يمكنك إنشاء حساب مباشرة من نافذة التسجيل.',
    'web.challenge.faq.a2': 'يمكن لمنصة Manyfold ربط وتنسيق أدوات وأطر عمل وكيل مثل Claude و Gemini CLI و Codex و Hermes و OpenClaw. اخترها حسب المهمة عند إنشاء وكيل، واجمع بين النماذج والأدوات عندما يكون ذلك مفيدًا؛ لا يؤثر اختيار النموذج على التقييم. يعتمد التوفر على قائمة الموفّر والنموذج الحالية في Manyfold.',
    'web.challenge.faq.a3': 'لا. يأتي التسجيل مع شهر واحد من Plus ورصيد بقيمة 30 دولارًا؛ يمكنك أيضًا ربط موفّريك الخاصين.',
    'web.challenge.faq.a4': 'أرسل بريدًا إلكترونيًا إلى hi@manyfold.ai — يرد فريق Manyfold بسرعة على أسئلة التسجيل والإعداد و API والإرسال.',
    'web.challenge.faq.a5': 'تدعم Manyfold العديد من الموفّرين والنماذج. افتح جلسة وكيل، وانقر على Configure، واختر الموفّر الذي يناسب المهمة؛ يمكنك أيضًا ربط موفّر API تملكه بالفعل واستخدام النماذج والخدمات التي تألفها.',
    'web.challenge.faq.a6.intro': 'بعد التسجيل، قم ببناء مشروعك في مساحة عمل Manyfold. بمجرد الموافقة على تسجيلك، يمكنك الإرسال من هذه الصفحة أو من صفحة حالتك.',
    'web.challenge.faq.a6.s2.h': '01 · الانتهاء والنشر',
    'web.challenge.faq.a6.s2.p': 'أكمل مشروعًا صالحًا للعمل وقم بإعداد رابط مشروع عام أو فيديو عرض توضيحي مدته 2-3 دقائق. يمكنك النشر في أي مكان؛ يُنصح باستخدام GitHub و Cloudflare.',
    'web.challenge.faq.a6.s3.h': '02 · إضافة تفاصيل إرسالك',
    'web.challenge.faq.a6.s3.p': 'املأ اسم المشروع ورابطًا عامًا ووصفًا قصيرًا. سيقوم الحكام بفتح الرابط لتجربته — إذا كان يتطلب تسجيل دخول أو رمز وصول، فضع التفاصيل في ملخصك.',
    'web.challenge.faq.a6.s4.h': '03 · الإرسال قبل الموعد النهائي',
    'web.challenge.faq.a6.s4.p': 'قم بالإرسال بحلول 12 أغسطس الساعة 24:00 (13 أغسطس، 00:00). يمكنك إعادة فتح النموذج وتحديث تفاصيلك حتى الموعد النهائي؛ سيتم استخدام أحدث إصدار. سيختار المقيّمون المتأهلين للتصفيات النهائية، وتعرض صفحة حالتك النتيجة.',
    'web.challenge.faq.a7': 'منصة Manyfold هي منصة تكامل لوكلاء الذكاء الاصطناعي تم تطويرها تحت مظلة NetMind.AI. توفر NetMind.AI البنية التحتية للذكاء الاصطناعي وموارد النماذج؛ بينما تركز Manyfold على تجربة المطورين، حيث تجمع بين الأدوات وأطر العمل والنماذج لبناء ونشر وإدارة أنظمة متعددة الوكلاء.',
    'web.challenge.faq.a8.cloudflare.h': 'Cloudflare: نشر المواقع والخدمات بسرعة',
    'web.challenge.faq.a8.cloudflare.p': 'تناسب Cloudflare Pages مواقع الويب ومشاريع الواجهة الأمامية. عندما تحتاج إلى منطق الواجهة الخلفية أو وظائف بدون خادم، ادمجها مع Cloudflare Workers للنشر عبر شبكة طرفية عالمية للحصول على سرعة وتوافر أفضل.',
    'web.challenge.faq.a8.composio.h': 'Composio: ربط الخدمات الخارجية',
    'web.challenge.faq.a8.composio.p': 'توفر Composio خوادم MCP وعمليات تكامل لمجموعة واسعة من التطبيقات، بما في ذلك Google Workspace و Notion و Slack و GitHub. يمكن للوكلاء قراءة البيانات واتخاذ الإجراءات مباشرةً، مما يقلل من تكلفة بناء والتحقق من تكاملات API بنفسك.',
    'web.challenge.faq.a8.github.h': 'GitHub: إدارة الكود وأتمتة CI/CD',
    'web.challenge.faq.a8.github.p': 'يُعد GitHub أكثر من مجرد مستودع للكود. يمكن لـ GitHub Actions أتمتة الاختبار والبناء والنشر، مما يسهل على الفرق إنشاء سير عمل CI/CD متكامل.',
    'web.challenge.faq.a9.cloudflare.1': 'انقر على أيقونة ملفك الشخصي، ثم انتقل إلى Profile ← API Tokens ← API Token Templates.',
    'web.challenge.faq.a9.cloudflare.2': 'اختر قالب Edit Cloudflare Workers، ثم قم بتعيين Account Resources إلى All accounts و Zone Resources إلى All zones.',
    'web.challenge.faq.a9.cloudflare.3': 'حدد Continue to summary ← Create Token، ثم انسخ الرمز إلى إعدادات اتصال Cloudflare في Manyfold.',
    'web.challenge.faq.a9.cloudflare.h': 'Cloudflare',
    'web.challenge.faq.a9.composio.1': 'بعد التسجيل، افتح Installed من القائمة اليسرى.',
    'web.challenge.faq.a9.composio.2': 'قم بالتمرير إلى MCP URL، وافتحه وانسخ مفتاح API المعروض هناك.',
    'web.challenge.faq.a9.composio.3': 'الصقه في إعدادات اتصال Composio في Manyfold واحفظه.',
    'web.challenge.faq.a9.composio.h': 'Composio',
    'web.challenge.faq.a9.github.1': 'سيوجهك Manyfold عادةً عبر GitHub OAuth.',
    'web.challenge.faq.a9.github.2': 'إذا طلب الاتصال رمزًا، فقم بإنشائه في GitHub Settings → Developer settings → Personal access tokens مع الأذونات التي يحتاجها مشروعك.',
    'web.challenge.faq.a9.github.3': 'عُد إلى اتصال GitHub في Manyfold، وأكمل التفويض أو أضف الرمز، ثم احفظ.',
    'web.challenge.faq.a9.github.h': 'GitHub',
    'web.challenge.faq.aDemoDeadline': 'لا — لا يوجد تسجيل منفصل لـ يوم العرض. تسجيلك في التحدي (يُغلق في 12 أغسطس الساعة 24:00، أي 13 أغسطس 00:00) هو تذكرتك، وتفاصيل الانضمام تظهر في صفحة حالتك قبل 13 أغسطس.',
    'web.challenge.faq.aDemoOnly': 'نعم. يحتفظ كل مشارك مسجل بمقعده في يوم العرض حتى بدون تقديم مشروع — تعال وشاهد المتأهلين للنهائيات وأدلِ بصوتك. لا يوجد تسجيل منفصل لـ يوم العرض؛ تسجيل التحدي (يُغلق في 12 أغسطس الساعة 24:00) هو التسجيل الوحيد.',
    'web.challenge.faq.aPresenter': 'بعد إغلاق التقديمات، يختار الحكام المتأهلين للنهائيات ويظهر القرار في صفحة حالة كل مشارك؛ يقدم المتأهلون عروضهم مباشرة في يوم العرض. تُمنح الجوائز على المسرح فقط — يفقد المتأهل الذي لا يحضر جائزته. كل متأهل يكمل عرضه التقديمي يفوز: يحصل الثلاثة الأوائل على جوائز المراكز، ويحصل جميع الآخرين على ذكر شرفي.',
