    'web.challenge.tl.s5.p': 'يفوز كل متأهل للنهائيات يكمل عرضاً تقديمياً مباشراً؛ يصوت الحاضرون لأفضل ثلاثة، ويحصل جميع الآخرين على إشادة شرفية.',
    'web.challenge.tl.s5.when': 'الخميس 13 أغسطس، 18:00',
    'web.challenge.why.c1.h': 'ابدأ مجاناً',
    'web.challenge.why.c1.p': 'سجل لتحصل على شهر واحد من Manyfold Plus ورصيد Manyfold API بقيمة 30 دولاراً، ثم ابدأ في البناء.',
    'web.challenge.why.c2.h': 'تنسيق مرن',
    'web.challenge.why.c2.p': 'قم بإدارة وتنسيق العديد من الوكلاء في مساحة عمل واحدة، مع اختيار إطار العمل والنموذج لكل مهمة: فئات رخيصة للأعمال الخفيفة، وأفضل النماذج عندما يكون التقييم مهماً.',
    'web.challenge.why.c3.h': 'اعرض عملك',
    'web.challenge.why.c3.p': 'تتم دعوة المتأهلين للنهائيات للتقديم في يوم العرض. يفوز كل مشروع يكمل عرضاً تقديمياً: يحصل الثلاثة الأوائل على جوائز المراكز، ويحصل جميع الآخرين على إشادة شرفية.',
