    'web.landing.ctaSecondaryCta': 'قراءة المستندات',
    'web.landing.faqA1': 'لا. كل إطار عمل يعمل بصورته الأصلية، بنموذج تنفيذه الخاص وإعدادات نماذجه ودلالات مساحة عمله. Manyfold هو الطبقة المحيطة بها: بيئة التشغيل ومساحة العمل والتنسيق والتسليم وقياس الاستهلاك. وحين يطرح إطار عمل شيئًا جديدًا، يصلك في اليوم نفسه.',
    'web.landing.faqA2': 'الجهاز الافتراضي يمنحك قدرة حوسبة فقط. أما Manyfold فيمنحك الجزء الذي كنت ستبنيه بعد ذلك: تهيئة إطار العمل، والجلسات الدائمة، والملفات والطرفية، وإعداد النماذج، والمهارات و MCP، والقنوات، والأتمتة، والاستهلاك لكل دور، لكل وكيل، في مكان واحد.',
    'web.landing.faqA3': 'لا. أوصِل حاسوبك المحمول أو خادمك عبر mf daemon، أو أضِف Dify و Langflow وغيرهما من الخدمات المدعومة كوحدات عمل مُهيّأة. بيئات التشغيل الخارجية تحتفظ بحدود قدراتها، ونحن نوضّح أين تقع تلك الحدود بدل التظاهر بأنها غير موجودة.',
    'web.landing.faqA4': 'وكيلك المستضاف خلف نقطة نهاية متوافقة مع OpenAI، بحيث تعمل حزم SDK الحالية دون تغيير. تنضم الاستدعاءات إلى نظام الجلسات والصلاحيات والاستهلاك نفسه الذي تستخدمه مساحة العمل على الويب. إنه وكيل تديره أنت، لا مجرد وسيط للنموذج.',
    'web.landing.faqA5': 'يبدأ معظم المطوّرين من مساحة العمل على الويب، ثم يربطون API بمنتج أو قناة بمحادثة الفريق. أما الفرق ذات التوجّه التشغيلي فتبدأ غالبًا بجدولة وقناة. كل الواجهات تصل إلى الوكلاء أنفسهم، فلا يكلّفك الترتيب شيئًا.',
    'web.landing.faqLead': 'إن كنت توازن بين هذا وبين بنائه بنفسك، فابدأ من هنا.',
    'web.landing.faqQ1': 'هل هذا مجرد غلاف حول Claude Code أو Codex؟',
