    'web.channels.settings.connectionHelp.matrix': 'تستطلع API نقطة Matrix ‎/sync‎ برمز وصول البوت — لا حاجة إلى عنوان URL عام أو إعداد رد اتصال. الغرف المشفّرة غير مدعومة؛ تُهمل الأحداث المشفّرة.',
    'web.channels.settings.connectionHelp.discord': 'تحتفظ API باتصال Discord Gateway — لا حاجة إلى عنوان URL عام أو إعداد رد اتصال. تأكد من تفعيل MESSAGE_CONTENT في بوابة المطوّرين ضمن Bot → Privileged Gateway Intents.',
    'web.channels.settings.connectionHelp.weixin': 'تستطلع API بوابة بوت Tencent iLink برمز البوت — لا حاجة إلى عنوان URL عام. حساب WeChat الشخصي للرسائل المباشرة فقط؛ لا تُسلَّم محادثات المجموعات. إذا انتهت صلاحية الجلسة (الرمز -14)، أعد مسح رمز QR وحدّث الرمز.',
    'web.channels.settings.webhookHelp.telegram': 'يُسجَّل webhook Telegram تلقائيًا عند حفظ بيانات الاعتماد — لا حاجة للصق أي شيء.',
    'web.channels.settings.webhookHelp.slack': 'الصق هذا الرابط في تطبيق Slack الخاص بك ضمن Event Subscriptions → Request URL.',
    'web.channels.settings.webhookHelp.lark': 'الصق هذا في {{platform}} Open Platform ← Event Subscriptions ← Request URL.',
    'web.channels.settings.webhookHelp.github': 'يضبط تدفق إنشاء تطبيق GitHub عنوان URL لهذا الـ webhook على التطبيق تلقائيًا؛ أما للتطبيقات المُنشأة يدويًا، فاضبطه كعنوان URL لـ webhook التطبيق مع أحداث issues وissue_comment.',
    'web.channels.settings.webhookHelp.other': 'الصق عنوان URL هذا في إعدادات اشتراك أحداث الموفّر الخاص بك.',
    'web.channels.settings.webhookHelp.line': 'يُضبط عنوان URL الخاص بـ webhook في LINE تلقائيًا عند حفظ بيانات الاعتماد — لا شيء للصقه. فعّل "Use webhook" في وحدة تحكم LINE Developers ضمن Messaging API، وعطّل رسائل الرد التلقائي هناك حتى لا يرد البوت مرتين.',
    'web.channels.settings.github.title': 'تطبيق GitHub',
    'web.channels.settings.github.connectedAs': 'متصل باسم',
    'web.channels.settings.github.mentionHint': '. أشر إليه في مشكلة أو تعليق لبدء تحويل.',
    'web.channels.settings.github.install': 'التثبيت على المستودعات',
    'web.channels.settings.github.installHint': 'يجب تثبيت التطبيق على كل مستودع ينبغي للوكيل الرد عليه. صلاحية الكتابة على المستودع (استنساخ/دفع/طلب سحب) تأتي من اتصال GitHub مرتبط بنفس الوكيل، وليس من هذا التطبيق.',
    'web.channels.settings.github.createHint': 'أنشئ تطبيق GitHub مخصصًا لهذه القناة — يرسل GitHub بيانات الاعتماد تلقائيًا وتُفعّل القناة نفسها. اترك المؤسسة فارغة لإنشائه في حسابك الشخصي.',
    'web.channels.settings.github.create': 'إنشاء تطبيق GitHub',
