    'web.channels.settings.slack.manifestHint': 'أنشئ تطبيق Slack من بيان والصق هذا JSON. يضبط عنوان URL الطلب (Request URL) واشتراكات الأحداث ونطاقات البوت وجميع أوامر الشرطة المائلة لهذه القناة. إذا كان تطبيق آخر مثبَّت يستخدم اسم أمر بالفعل (مثل',
    'web.channels.settings.slack.manifestHintSuffix': ')، سيحذّر Slack عند التثبيت — أعد تسميته في البيان أولاً. ادعُ البوت إلى كل قناة ليتمكن من النشر فيها.',
