    'web.channels.settings.setupMode.lark': 'وضع إعداد Lark',
    'web.channels.settings.setupMode.weixin': 'وضع إعداد WeChat',
    'web.channels.settings.help.telegramCreate': 'أنشئ بوتًا عبر @BotFather والصق الرمز. سنسجّل الـ webhook نيابةً عنك.',
    'web.channels.settings.help.telegramEdit': 'اترك المستخدمين أو محادثات المجموعات المسموح بها فارغة للسماح للجميع. يمكن للمشغّلين تشغيل أوامر على مستوى الوكيل مثل /model؛ وبدون مشغّلين، تُعطَّل هذه الأوامر من Telegram.',
    'web.channels.settings.help.slackCreate': 'بعد الحفظ، الصق عنوان URL الوارد الخاص بالقناة في تطبيق Slack الخاص بك ضمن Event Subscriptions. اترك المستخدمين المسموح بهم فارغًا للسماح لأي شخص في مساحة العمل باستخدام البوت. يمكن للمشغّلين تشغيل أوامر على مستوى الوكيل مثل /model؛ وبدون مشغّلين، يُعطَّل /model من Slack.',
    'web.channels.settings.help.slackEdit': 'اترك المستخدمين المسموح بهم فارغًا للسماح لأي شخص في مساحة العمل باستخدام البوت. يمكن للمشغّلين تشغيل أوامر على مستوى الوكيل مثل /model؛ وبدون مشغّلين، يُعطَّل /model من Slack.',
    'web.channels.settings.help.linearCreate': 'أنشئ تطبيقًا في مساحة عمل Linear الخاصة بك، وفعّل الـ webhooks مع أحداث جلسات الوكيل، والصق عنوان URL الوارد الخاص بالقناة هناك بعد الحفظ. تتيح بيانات اعتماد العميل لـ Manyfold إصدار رمز تطبيقه الخاص؛ زوّد برمز وصول بدلاً من ذلك إذا أصدرته بنفسك. اترك المستخدمين المسموح بهم فارغًا للسماح لأي شخص في مساحة العمل بالإشارة إلى الوكيل.',
    'web.channels.settings.help.githubCreate': 'أنشئ القناة أولاً، ثم استخدم "إنشاء تطبيق GitHub" في صفحتها — يرسل GitHub بيانات اعتماد التطبيق تلقائيًا. أشر إلى التطبيق في مشكلة لبدء تحويل. اترك المستودعات فارغة للرد على كل مستودع مثبَّت عليه التطبيق.',
    'web.channels.settings.help.discordCreate': 'يستخدم Discord بوابة WebSocket — لا حاجة إلى عنوان URL عام. فعّل نية MESSAGE_CONTENT في بوابة المطوّرين ضمن Bot → Privileged Gateway Intents، وإلا فلن يرى البوت نص الرسائل.',
    'web.channels.settings.help.matrixCreate': 'يستخدم Matrix استطلاع ‎/sync‎ الطويل — لا حاجة إلى عنوان URL لـ webhook. الغرف المشفّرة غير مدعومة؛ تُهمل الأحداث المشفّرة.',
    'web.channels.settings.help.weixinCreate': 'حساب WeChat الشخصي عبر بوابة بوت Tencent iLink — رسائل مباشرة فقط، لا حاجة إلى عنوان URL لـ webhook. اترك معرّفات المشغّل فارغة لتعطيل الأوامر على مستوى الوكيل.',
    'web.channels.settings.help.larkManual': 'اترك المستخدمين المسموح بهم فارغًا للسماح لأي شخص بالوصول إلى البوت. يمكن للمشغّلين تشغيل أوامر على مستوى الوكيل مثل /model؛ وبدون مشغّلين، يُعطَّل /model من Feishu/Lark.',
    'web.channels.settings.help.weixinEdit': 'حساب WeChat الشخصي للرسائل المباشرة فقط. اترك معرّفات المشغّل فارغة لتعطيل الأوامر على مستوى الوكيل (مثل /model).',
    'web.channels.settings.help.whatsappEdit': 'يتصل WhatsApp عبر WhatsApp Web، لذا لا تحتاج هذه القناة إلى webhook URL. اترك المرسلين أو المحادثات الجماعية المسموح بها فارغة للسماح للجميع. يمكن للمشغّلين تنفيذ أوامر على مستوى الوكيل مثل ‎/model؛ وبدون مشغّلين تُعطَّل هذه الأوامر من WhatsApp. يمكن كتابة المرسل كرقم هاتف أو كـ jid.',
    'web.channels.settings.help.linearEdit': 'يعرض النشاط التفكير واستدعاءات الأدوات والخطة في جلسة Linear أثناء عمل الوكيل؛ يعرض "النهائي فقط" النتيجة وحدها. يستبدل تدوير بيانات الاعتماد جميعها دفعة واحدة، لذا أعد إدخال سر التوقيع مع أي تغيير.',
    'web.channels.settings.help.githubEdit': 'إذا تُركت الحسابات المسموح بها فارغة، يُستخدم بدلًا منها ضابط الارتباط (مالك المستودع وأعضاء المؤسسة والمتعاونون افتراضيًا — أضف NONE لفتحه للجميع). إضافة تصنيف التفويض إلى مشكلة يبدأ تحويلًا دون إشارة. اترك حسابات المشغّل فارغة لتعطيل الأوامر على مستوى الوكيل (مثل /model).',
    'web.channels.settings.help.lineCreate': 'أنشئ قناة Messaging API في وحدة تحكم LINE Developers، وأصدر رمز وصول قناة طويل الأمد، والصق الاثنين هنا. نحن نضبط عنوان URL الخاص بـ webhook نيابةً عنك — لكن عليك تفعيل "Use webhook" في وحدة التحكم. الردود نص عادي دون معاينة مباشرة، وكل رد يُحتسب ضمن حصة الرسائل في خطة LINE الخاصة بك.',
    'web.channels.settings.help.lineEdit': 'اترك المستخدمين أو معرّفات المجموعات المسموح بها فارغة للسماح للجميع. يمكن للمشغّلين تشغيل أوامر على مستوى الوكيل مثل /model؛ وبدون مشغّلين، تُعطَّل هذه الأوامر من LINE. تدوير بيانات الاعتماد يستبدل الاثنين معًا، لذا أعد إدخال سر القناة ورمز الوصول معًا.',
    'web.channels.settings.errors.larkWebhookCredentials': 'تتطلب قنوات Webhook في Lark/Feishu رمز تحقق أو مفتاح تشفير.',
